// ⚠ 使用前必读 README.md + CONTEXT.md。app 不直接 import——经 createStore。
//
// safe-resolve（深模块）—— **永不丢字节**地化解本地↔云端分歧。单一职责 = 那条不可重排的顺序：
//   备份先于覆盖(A4/A10) · 采纳前校验真容器(N2,挡 captive-portal HTML) · 采纳后置 etag(R1) ·
//   lost-response 自愈(B5) · 冲突派发(keepMine/takeCloud/cancel)。
// 吃：cloud(pull/weakOverride) + local(backup/save) + local-head(markSynced 落地谱系)。
import { toU8, bytesEqual } from "./substrate.js";
import { reportStoreError } from "./error-handling.js"; // 全接但分级：静默 swallow 也 funnel（不改控制流）
export function createSafeResolve(cfg) {
    const { cloud, local, head, localDirty = () => false, validateAdopt, unseal = (_n, blob) => Promise.resolve(blob), onReplacing = () => { }, looksEncrypted = () => Promise.resolve(false), } = cfg;
    // 安全拉取覆盖：先 backup（dirty 才备；失败即 abort，绝不 pull/覆盖）→ 拉 → 校验 → 覆盖 → 采纳后置 etag → adopt。
    // 持久态只在原子点改；强退任一 await 点可重入。
    // forceBackup（2026-08-25 user 拍板，案卷 20260825-cloud-override-adopt-noop-case.md §5 前提）：
    //   takeCloud 是「文件版本模型」的换世界线，不是 workspace 操作——被换掉的当前世界线**无条件**先进 .backup。
    //   （clean-skip 的「本地可从云重取」论据在 takeCloud 场景恰恰失效过：本地随后覆写云端时，云端那版就不再兜底。）
    //   freshness 的静默快进（clean fast-forward）不传它——ADR-0016 的不 spam .backup 决策不动。
    async function safePull(name, { adopt, forceBackup = false } = {}) {
        onReplacing(true);
        try {
            let backupName;
            // clean 本地 = 可从云重取的已知版本，无未见内容可丢 → 跳 backup（ADR-0016，不 spam .backup）。
            //   ⚠ 该论据的前提是**谱系已知**（seenBase 非 null：本地 == 云端某已知版）。!base（从未 synced /
            //   durable 双轨丢失，如 localStorage 被清而 IDB 幸存——dirty 标志会同批丢）时本地字节出身不明，
            //   「clean」不可信 → 覆盖前必 move-aside（§A：every overwrite is move-aside）。场景罕见，不构成 spam。
            if (forceBackup || head.isDirtyAnywhere(name) || localDirty() || head.seenBase(name) == null) { // anywhere：任一 tab 有未推 → 覆盖前必 backup
                try {
                    backupName = await local.backup(name);
                }
                catch (e) {
                    reportStoreError(e, "warning");
                    return { ok: false, reason: "backup-failed", error: e };
                } // dirty 备份失败→中止 pull（不覆盖），degraded surface
            }
            const r = await cloud.pull(name);
            if (!r)
                return { ok: false, reason: "cloud-vanished", backupName };
            // 库对加密透明：先解密，validateAdopt 验的是**明文**（app 看真明文文档，不是密文容器）。
            const plain = await unseal(name, r.blob); // 加密但锁定 → null（无密码解不开）
            // N2：坏字节（captive-portal 200-HTML / 损坏云副本）→ 拒绝，绝不覆盖唯一一份好本地（clean 没 backup）。
            //   锁定解不开 → 退验加密容器封套（captive-portal HTML 不是合法容器；无密码时能做的最强校验）。
            const ok = plain != null ? await validateAdopt(plain) : await looksEncrypted(r.blob);
            if (!ok)
                return { ok: false, reason: "invalid-cloud-bytes", backupName };
            await local.save(name, r.blob); // 覆盖本地（存 at-rest/sealed 字节；dirty 时原件已备份）
            head.markSynced(name, r.item?.eTag ?? null); // 采纳后置（R1）：etag/dirty 只在 save 成功后推进
            if (adopt && plain != null)
                await adopt(plain, name); // 复用已解密明文；锁定解不开则只快进落盘、不 adopt
            return { ok: true, backupName };
        }
        finally {
            onReplacing(false);
        }
    }
    // lost-response 自愈：412 可能是自己已落盘的写。拉云逐字节比对，相等即采纳（B5/W1）。
    async function tryHeal(name, bytes) {
        let pulled;
        try {
            pulled = await cloud.pull(name);
        }
        catch (e) {
            reportStoreError(e, "log");
            return false;
        }
        if (!pulled)
            return false;
        if (bytesEqual(await toU8(pulled.blob), bytes)) {
            head.markSynced(name, pulled.item?.eTag ?? null); // 自愈 → 这次推等价已在云端
            return true;
        }
        return false;
    }
    // keepMine：云端→.backup，再 force-push 本地（never-lose 覆盖）。本地胜、loser 进 .backup → 落地为 synced。
    async function weakOverride(name, bytes) {
        const r = await cloud.weakOverride(name, bytes, { encrypted: await looksEncrypted(bytes) });
        // F0 红线同款 deferred guard（push.ts:73-77 的形状，2026-08-25 案卷 §4(b) 补）：provider 没回 item/eTag
        //   = 落地未确认（响应丢失/分块吞 body）。旧版无条件 markSynced(name, null)——dirty 清、etag 清、badge
        //   假 synced，且下次推 no-base fail 409。→ 不 markSynced（dirty/parent 原样保住），报 deferred；
        //   下次 push If-Match 旧 base → 若上传其实落了则 412 → tryHeal 逐字节比对自愈（组合闭环）。
        if (!(r.item && r.item.eTag))
            return { backedUp: r.backedUp, deferred: true };
        head.markSynced(name, r.item.eTag);
        return { backedUp: r.backedUp, deferred: false };
    }
    // 3 选项派发（README.md §7）：takeCloud=safePull · keepMine=weakOverride · cancel=什么都不动（留 dirty）。
    async function resolveConflict(name, choice, ctx = {}) {
        if (choice === "takeCloud") {
            const r = await safePull(name, { adopt: ctx.adopt, forceBackup: true }); // 换世界线 → 当前世界线无条件进 .backup（user 2026-08-25 拍板）
            return r.ok
                ? { status: "resolved", resolution: "takeCloud", backupName: r.backupName }
                : { status: "unresolved", reason: r.reason, backupName: r.backupName };
        }
        if (choice === "keepMine" && ctx.bytes != null) {
            const r = await weakOverride(name, ctx.bytes);
            if (r.deferred)
                return { status: "unresolved", reason: "deferred", backedUp: r.backedUp }; // 落地未确认 ≠ 已化解：dirty 保住，下次推自愈（tryHeal）
            return { status: "resolved", resolution: "keepMine", backedUp: r.backedUp };
        }
        return { status: "cancelled" };
    }
    return { safePull, tryHeal, weakOverride, resolveConflict };
}
